using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Mediator;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_M_00008 : MediatorTestBase
    {
        [TestMethod]
        public void Requests_Have_To_Be_Internal()
        {
            var publicRequests = (from implementation in MediatorImplementations
                                  where implementation.Request != null
                                  where implementation.Request.Modifiers.Any(m => m == Modifier.Public)
                                  select new
                                  {
                                      Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullQualifiedName:  {implementation.Handler.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Current:    

{implementation.Request.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should be:  

{implementation.Request.SyntaxTree.Replace("public", "internal").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                  }).ToImmutableList();


            Assert.IsTrue(publicRequests.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00008

Your MediatR requests have not to be public. A request is an abstraction for your http requests and should not be public.
If you have testing issues, test your interface (API endpoint) and not the implementation details.

Found:{publicRequests.Count}

{publicRequests.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
